def browser_file_upload(paths=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0120000" if __import__("os").path.isdir("./environment_mix/0120000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if paths is not None:
        if not isinstance(paths, list):
            return _err("VALIDATION_ERROR", "paths must be an array of strings when provided")
        for i, p in enumerate(paths):
            if not isinstance(p, str):
                return _err("VALIDATION_ERROR", "each path must be a string", index=i)
            if not os.path.isabs(p):
                return _err("VALIDATION_ERROR", "each path must be an absolute path", path=p, index=i)
            # must be readable file
            if not os.path.isfile(p):
                return _err("NOT_FOUND", "file not found", path=p, index=i)
            try:
                with open(p, "rb") as _fh:
                    _fh.read(1)
            except OSError:
                return _err("UNAUTHORIZED", "file cannot be read", path=p, index=i)

    # Load current page state (single-row object or empty)
    st = _load("page_state.json")
    if st == []:
        st = {}
    if not isinstance(st, dict):
        return _err("CONFLICT", "page_state is corrupted")

    # Must have an active tab
    tabs = st.get("tabs")
    if not isinstance(tabs, list) or not any(isinstance(t, dict) and t.get("active") is True for t in tabs):
        return _err("NOT_FOUND", "no active tab to receive file upload")

    # Simulate file chooser presence: require dialog.type == "fileChooser" to accept/cancel
    dialog = st.get("dialog")
    if not isinstance(dialog, dict) or dialog.get("type") != "fileChooser":
        return _err("CONFLICT", "no file chooser is currently open")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Persist mutation: append console message and resolve dialog
    console = st.get("console")
    if not isinstance(console, list):
        console = []
    if paths is None:
        console.append({"type": "info", "text": "File chooser cancelled"})
        st["dialog"] = None
        st["console"] = console
        st["last_upload"] = {"status": "cancelled", "paths": [], "ts": now}
        _save("page_state.json", st)
        return {
            "status": "cancelled",
            "resolved": True,
            "paths": [],
            "timestamp": now
        }

    console.append({"type": "info", "text": "Files supplied to chooser: " + ", ".join(paths)})
    st["dialog"] = None
    st["console"] = console
    st["last_upload"] = {"status": "uploaded", "paths": list(paths), "ts": now}
    _save("page_state.json", st)

    return {
        "status": "uploaded",
        "resolved": True,
        "paths": list(paths),
        "timestamp": now
    }

