def browser_install(browser=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0120000" if __import__("os").path.isdir("./environment_mix/0120000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    allowed = {"chromium", "firefox", "webkit"}
    if browser is not None:
        if not isinstance(browser, str):
            return _err("VALIDATION_ERROR", "browser must be a string")
        if browser not in allowed:
            return _err("VALIDATION_ERROR", "unsupported browser", allowed=sorted(allowed))

    # Record installation in page_state so the datastore moves (no separate audit collection exists in schema)
    st = _load("page_state.json")
    if st == []:
        st = {}
    if not isinstance(st, dict):
        return _err("CONFLICT", "page_state is corrupted")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    target = browser or "chromium"

    installed = st.get("installed_browsers")
    if not isinstance(installed, list):
        installed = []
    if target not in installed:
        installed.append(target)

    console = st.get("console")
    if not isinstance(console, list):
        console = []
    console.append({"type": "info", "text": f"Browser installed: {target}"})

    st["installed_browsers"] = installed
    st["console"] = console
    st["last_install"] = {"browser": target, "ts": now}
    _save("page_state.json", st)

    return {
        "browser": target,
        "installed": True,
        "installed_browsers": installed,
        "timestamp": now
    }

