def browser_snapshot(includeConsole=None, includeNetwork=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0120000" if __import__("os").path.isdir("./environment_mix/0120000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate flags (unknown fields refused via signature + **_extra capture)
    if _extra:
        return _err("VALIDATION_ERROR", "unknown fields in request body", unknown=sorted(list(_extra.keys())))
    if includeConsole is not None and not isinstance(includeConsole, bool):
        return _err("VALIDATION_ERROR", "includeConsole must be boolean when provided")
    if includeNetwork is not None and not isinstance(includeNetwork, bool):
        return _err("VALIDATION_ERROR", "includeNetwork must be boolean when provided")

    st = _load("page_state.json")
    if st == []:
        st = {}
    if not isinstance(st, dict):
        return _err("CONFLICT", "page_state is corrupted")

    tabs = st.get("tabs")
    if not isinstance(tabs, list) or not any(isinstance(t, dict) and t.get("active") is True for t in tabs):
        return _err("NOT_FOUND", "no active tab or page available to snapshot")

    snap = st.get("snapshot")
    if snap is None:
        snap = []
    if not isinstance(snap, list):
        return _err("CONFLICT", "snapshot is corrupted")

    # Persist that a snapshot was taken (service dynamics; no audit collection exists)
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    st["last_snapshot_ts"] = now
    st["snapshot_count"] = int(st.get("snapshot_count") or 0) + 1
    _save("page_state.json", st)

    resp = {
        "url": st.get("current_url"),
        "title": st.get("title"),
        "viewport": st.get("viewport"),
        "elements": snap,
        "timestamp": now,
    }

    if includeConsole:
        c = st.get("console")
        resp["console"] = c if isinstance(c, list) else []
    if includeNetwork:
        n = st.get("network")
        resp["network"] = n if isinstance(n, list) else []

    return resp

