def browser_click(element, ref, button="left", doubleClick=False, modifiers=None):
    import json, os
    st = json.load(open(os.path.join(_DB, "page_state.json"), encoding="utf-8"))
    target = next((e for e in st.get("snapshot", []) if e["ref"] == ref), None)
    return {"action": "click", "element": element, "ref": ref, "button": button,
            "doubleClick": bool(doubleClick), "modifiers": modifiers or [],
            "resolved": target, "result": "clicked"}

